// Number of holes set by the interface constant A
float numHoles = max(A, 1.0); 

// Polar coordinates on the space XY plane (variable 'p' in the script editor)
float r_polar = length(p.xy);
float angle = atan(p.y, p.x);

// Angular repetition: fold space based on the number of holes
float angle_rep = mod(angle + 3.14159265 / numHoles, 6.2831853 / numHoles) - 3.14159265 / numHoles;

// SDF distance from the subtracting cylinders (centered along ring D)
float d_hole = sqrt(r_polar * r_polar + D * D - 2.0 * r_polar * D * cos(angle_rep)) - B;

// SDF distance of the main torus
float d_torus = length(vec2(r_polar - D, p.z)) - C;

// Final step: explicitly return the smooth subtraction using smax
return smax(d_torus, -d_hole, max(E, 0.01));
